function DateBox($hostControl,$x,$y,$w){$c=New-Object Windows.Forms.DateTimePicker;$c.Format='Custom';$c.CustomFormat='yyyy-MM-dd';$c.Value=[datetime]'2026-10-31';$c.SetBounds($x,$y,$w,28);$hostControl.Controls.Add($c);return $c}
function TextBox($hostControl,$x,$y,$w,$h=28){$c=New-Object Windows.Forms.TextBox;$c.SetBounds($x,$y,$w,$h);if($h -gt 30){$c.Multiline=$true;$c.ScrollBars='Vertical'};$hostControl.Controls.Add($c);return $c}
function Write-Request($obj){$requestDir=if($ws){Join-Path $ws 'logs/requests'}else{Join-Path $base 'evidence/project-requests'};New-Item -ItemType Directory $requestDir -Force|Out-Null;$path=Join-Path $requestDir ('request-'+[guid]::NewGuid().ToString('N')+'.json');$obj|ConvertTo-Json -Depth 12|Set-Content $path -Encoding utf8;return $path}
